namespace AISmartLearning.API.Models;
public sealed class Role { public int RoleId {get;set;} public string RoleName {get;set;}=""; public ICollection<User> Users {get;set;}=new List<User>(); }
public sealed class User { public int UserId {get;set;} public string FullName {get;set;}=""; public string Email {get;set;}=""; public string PasswordHash {get;set;}=""; public int RoleId {get;set;} public bool IsActive {get;set;}=true; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public Role? Role {get;set;} public ICollection<Conversation> Conversations {get;set;}=new List<Conversation>(); public ICollection<InteractionLog> InteractionLogs {get;set;}=new List<InteractionLog>(); }
public sealed class Conversation { public int ConversationId {get;set;} public int UserId {get;set;} public string Title {get;set;}="New conversation"; public DateTime StartedAt {get;set;}=DateTime.UtcNow; public DateTime? EndedAt {get;set;} public string Status {get;set;}="Active"; public User? User {get;set;} public ICollection<ConversationMessage> Messages {get;set;}=new List<ConversationMessage>(); }
public sealed class ConversationMessage { public long MessageId {get;set;} public int ConversationId {get;set;} public string SenderType {get;set;}="User"; public string MessageText {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public Conversation? Conversation {get;set;} }
public sealed class InteractionLog { public long LogId {get;set;} public int UserId {get;set;} public int? ConversationId {get;set;} public string Action {get;set;}=""; public string Details {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; public User? User {get;set;} public Conversation? Conversation {get;set;} }